#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define MAX_HEADER_SIZE 256
#define MAX_BODY_SIZE 4096
#define MAX_CHUNK_SIZE 1024

typedef struct {
    char method[16];
    char path[256];
    char headers[MAX_HEADER_SIZE];
    uint16_t content_length;
    char *body;
    size_t body_capacity;
    size_t body_written;
} http_request_t;

typedef struct {
    int chunked;
    int content_length_seen;
    uint16_t declared_length;
} transfer_info_t;

static int parse_transfer_encoding(http_request_t *req, transfer_info_t *info) {
    // Check for Transfer-Encoding: chunked
    if (strstr(req->headers, "Transfer-Encoding: chunked") != NULL) {
        info->chunked = 1;
        return 0;
    }
    // Check for Content-Length
    const char *cl = strstr(req->headers, "Content-Length: ");
    if (cl) {
        info->content_length_seen = 1;
        long val = strtol(cl + 16, NULL, 10);
        if (val < 0 || val > 65535) return -1;
        info->declared_length = (uint16_t)val;
        req->content_length = info->declared_length;
    }
    return 0;
}

static int validate_chunk_size(size_t chunk_size, size_t total_so_far, size_t max_allowed) {
    // Validate that adding this chunk won't exceed the maximum
    size_t new_total = total_so_far + chunk_size;
    // Safe: size_t is large enough that overflow is not practical
    if (new_total > max_allowed) {
        return -1;
    }
    return 0;
}

static int allocate_body(http_request_t *req, size_t initial_size) {
    if (initial_size > MAX_BODY_SIZE) {
        initial_size = MAX_BODY_SIZE;
    }
    req->body = (char *)malloc(initial_size);
    if (!req->body) return -1;
    req->body_capacity = initial_size;
    req->body_written = 0;
    memset(req->body, 0, initial_size);
    return 0;
}

static int append_to_body(http_request_t *req, const char *data, size_t len) {
    // This trusts that validation has already been done
    if (req->body_written + len > req->body_capacity) {
        return -1;
    }
    memcpy(req->body + req->body_written, data, len);
    req->body_written += len;
    return 0;
}

int process_chunked_body(http_request_t *req, const char *raw_body, size_t raw_len) {
    transfer_info_t info = {0};
    if (parse_transfer_encoding(req, &info) != 0) return -1;

    if (!info.chunked) {
        // Simple content-length based read
        if (allocate_body(req, req->content_length) != 0) return -1;
        size_t to_copy = raw_len < req->content_length ? raw_len : req->content_length;
        return append_to_body(req, raw_body, to_copy);
    }

    // Chunked transfer: allocate based on declared Content-Length hint if available
    size_t alloc_hint = info.content_length_seen ? info.declared_length : MAX_BODY_SIZE;
    if (allocate_body(req, alloc_hint) != 0) return -1;

    // Parse chunks
    size_t total_received = 0;
    const char *ptr = raw_body;
    const char *end = raw_body + raw_len;

    while (ptr < end) {
        // Read chunk size (hex)
        char size_buf[8] = {0};
        int i = 0;
        while (ptr < end && *ptr != '\r' && *ptr != '\n' && i < 7) {
            size_buf[i++] = *ptr++;
        }
        // Skip CRLF
        while (ptr < end && (*ptr == '\r' || *ptr == '\n')) ptr++;

        unsigned long chunk_size = strtoul(size_buf, NULL, 16);
        if (chunk_size == 0) break; // End of chunks
        if (chunk_size > MAX_CHUNK_SIZE) return -1;

        // Validate using size_t arithmetic - no overflow possible
        if (validate_chunk_size(chunk_size, total_received, req->body_capacity) != 0) {
            return -1;
        }

        // Copy chunk data
        size_t avail = end - ptr;
        size_t to_copy = chunk_size < avail ? chunk_size : avail;

        // Direct write using validated total
        memcpy(req->body + total_received, ptr, to_copy);
        total_received += chunk_size;

        ptr += to_copy;
        // Skip trailing CRLF
        while (ptr < end && (*ptr == '\r' || *ptr == '\n')) ptr++;
    }

    req->body_written = total_received;
    return 0;
}

int main(int argc, char **argv) {
    http_request_t req = {0};
    strcpy(req.method, "POST");
    strcpy(req.path, "/api/upload");
    strcpy(req.headers, "Transfer-Encoding: chunked\r\nContent-Length: 512\r\n");

    // Simulated chunked body input
    const char *test_body = "A\r\nHelloWorld\r\n0\r\n";
    int result = process_chunked_body(&req, test_body, strlen(test_body));
    if (result == 0) {
        printf("Body (%zu bytes): %.*s\n", req.body_written, (int)req.body_written, req.body);
    } else {
        printf("Error processing body\n");
    }
    free(req.body);
    return 0;
}
